/**
 * RuntimePorts — the full set of port interfaces the orchestrator core depends on.
 *
 * A profile factory creates one RuntimePorts bundle at startup; the bundle is
 * then injected into the orchestrator concerns. The core never touches concrete
 * adapter classes — only this interface bundle.
 */

import type {
  ExecutorPort,
  CompletionBrokerPort,
  BriefingTransportPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "@workflow/runtime-abi";

export interface RuntimePorts {
  /** Spawn an executor; return a handle immediately (async in Wave 3+). */
  executor: ExecutorPort;

  /** Completion queue — in-flight registry + peek-and-lock drain. */
  broker: CompletionBrokerPort;

  /** Deliver briefings to executors. */
  briefing: BriefingTransportPort;

  /** Read/write workflow state (task YAMLs, logs). */
  workflowState: WorkflowStatePort;

  /** Provide credentials (GitHub token, SSH key path) to executors. */
  credential: CredentialPort;

  /** Materialize workspace repos (clone + pull). */
  workspacePull: WorkspacePullPort;

  /** Emit structured events / metrics. */
  emitter: EventEmitterPort;

  /** Control cycle cadence (sleep between cycles). */
  scheduler: SchedulerPort;

  /** Wall-clock time and sleep (mockable in tests). */
  clock: ClockPort;
}

