/**
 * Write a fake docker binary to dir/docker.
 *
 * The fake binary simulates:
 *  - `docker run -d ...` — writes state, spawns the runner script from
 *     FAKE_RUNNER_PATH env, returns a fake container ID
 *  - `docker wait <id>` — polls state file until the process exits
 *  - `docker rm <id>` — removes state entry
 *  - `docker ps -a --filter label=... --format ...` — lists state entries
 *  - `docker stop <id>` — no-op (signals process via state)
 *
 * State is kept as JSON in stateDir/containers.json.
 */
function writeFakeDocker(dir: string, stateDir: string): string {
  const dockerBin = join(dir, "docker");
  const script = `#!/usr/bin/env node
'use strict';
const { execFileSync, spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const cp = require('node:child_process');

const STATE_FILE = ${JSON.stringify(join(stateDir, "containers.json"))};

function loadState() {
  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8')); } catch { return {}; }
}
function saveState(s) {
  fs.writeFileSync(STATE_FILE, JSON.stringify(s, null, 2));
}

const args = process.argv.slice(2);
const cmd = args[0];

// ── docker run -d ──────────────────────────────────────────────────────────
if (cmd === 'run' && args.includes('-d')) {
  const envVars = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-e' && args[i+1]) {
      const [k, ...rest] = args[i+1].split('=');
      envVars[k] = rest.join('=');
      i++;
    }
  }
  const runnerPath = process.env.FAKE_RUNNER_PATH;
  if (!runnerPath) {
    process.stderr.write('FAKE_RUNNER_PATH not set\\n');
    process.exit(1);
  }
  const containerId = crypto.randomBytes(12).toString('hex');
  const child = cp.spawn('node', [runnerPath], {
    env: { ...process.env, ...envVars },
    stdio: 'inherit',
    detached: true,
  });
  child.unref();
  const state = loadState();
  state[containerId] = { pid: child.pid, exitCode: null, labels: {} };
  // Extract label values
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--label' && args[i+1]) {
      const [lk, lv] = args[i+1].split('=');
      state[containerId].labels[lk] = lv;
      i++;
    }
  }
  saveState(state);
  process.stdout.write(containerId + '\\n');
  process.exit(0);
}

// ── docker wait <id> ───────────────────────────────────────────────────────
if (cmd === 'wait') {
  const cid = args[1];
  const maxWait = 30000;
  const start = Date.now();
  const poll = () => {
    const state = loadState();
    if (!state[cid]) { process.stdout.write('137\\n'); process.exit(0); }
    const { pid } = state[cid];
    // Check if process is still running
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    if (!running) {
      const exitCode = state[cid].exitCode ?? 0;
      process.stdout.write(String(exitCode) + '\\n');
      process.exit(0);
    }
    if (Date.now() - start > maxWait) {
      process.stdout.write('1\\n');
      process.exit(0);
    }
    setTimeout(poll, 100);
  };
  poll();
  return;
}

// ── docker rm <id> ─────────────────────────────────────────────────────────
if (cmd === 'rm') {
  const cid = args[1];
  const state = loadState();
  delete state[cid];
  saveState(state);
  process.exit(0);
}

// ── docker stop <id> ──────────────────────────────────────────────────────
if (cmd === 'stop') {
  const cid = args[1];
  const state = loadState();
  if (state[cid]) {
    try { process.kill(state[cid].pid, 'SIGTERM'); } catch {}
  }
  process.exit(0);
}

// ── docker ps -a --filter label=... --format ... ─────────────────────────
if (cmd === 'ps') {
  const state = loadState();
  const lines = [];
  for (const [cid, entry] of Object.entries(state)) {
    const { pid, labels, exitCode } = entry;
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    const status = running ? 'Up' : \`Exited (\${exitCode ?? 0}) 1 second ago\`;
    const handle = labels['platform.handle'] ?? '';
    if (handle) {
      lines.push(cid + '\\t' + handle + '\\t' + status);
    }
  }
  process.stdout.write(lines.join('\\n') + (lines.length ? '\\n' : ''));
  process.exit(0);
}

process.stderr.write('fake-docker: unknown command: ' + cmd + '\\n');
process.exit(1);
`;
  writeFileSync(dockerBin, script, { mode: 0o755 });
  return dockerBin;
}

// ── Suite setup ───────────────────────────────────────────────────────────────

let broker: InMemoryBrokerAdapter;
let callbackUrl: string;

beforeEach(async () => {
  broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
  await broker.start();
  callbackUrl = broker.getCallbackUrl()!;
});

afterEach(async () => {
  await broker.stop();
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

// ── 1. Happy path ─────────────────────────────────────────────────────────────

describe("DockerRunAdapter — happy path", () => {
  it("submit() returns handle immediately; broker delivers the result via callback", async () => {
    const dir = makeTmpDir("dr-happy-");
    const stateDir = makeTmpDir("dr-happy-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-happy-001";

    // Fake runner: POSTs valid result to broker.
    const runnerPath = join(dir, "fake-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/99" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({`,
        `  hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `  method: "POST",`,
        `  headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `}, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", (e) => { process.stderr.write(e.message + "\\n"); process.exit(1); });`,
        `req.write(body); req.end();`,
      ].join("\n"),
      "utf-8",
    );

    const dockerBin = writeFakeDocker(dir, stateDir);
    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0, // disable in test
    });

    const handle = await adapter.submit(
      makeInput({ resultPath, callbackUrl, nonce }),
    );
    // Inject FAKE_RUNNER_PATH via env so fake docker knows which runner to spawn.
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    expect(typeof handle).toBe("string");
    expect(handle.length).toBeGreaterThan(0);
    expect(adapter.supervisionSize()).toBe(1);

    const completion = await waitForCompletion(broker);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");
    expect(completion.metadata.task_id).toBe("T8");

    await adapter.ack(handle);
    expect(adapter.supervisionSize()).toBe(0);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 2. Wrapper crash before POST ──────────────────────────────────────────────

describe("DockerRunAdapter — wrapper crash before POST", () => {
  it("safety net fires synthetic failed completion when container exits without POSTing", async () => {
    const dir = makeTmpDir("dr-crash-");
    const stateDir = makeTmpDir("dr-crash-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-crash-001";

    // Fake runner: exits non-zero without POSTing anything.
    const runnerPath = join(dir, "crash-runner.cjs");
    writeFileSync(runnerPath, `process.exit(1);\n`, "utf-8");

    const dockerBin = writeFakeDocker(dir, stateDir);
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 200,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    const completion = await waitForCompletion(broker, 12_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("failed");
    expect(String(completion.result.blocked_reason)).toMatch(/runner_crashed|runner_no_callback/);

    await broker.ack(handle);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 3. Broker-reject (replay) ─────────────────────────────────────────────────

describe("DockerRunAdapter — broker-reject replay", () => {
  it("second POST after ack returns 401; only one completion delivered", async () => {
    const dir = makeTmpDir("dr-replay-");
    const stateDir = makeTmpDir("dr-replay-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-replay-001";

    // Fake runner: POSTs result, then attempts a replay POST.
    const runnerPath = join(dir, "replay-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `function doPost(cb) {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({`,
        `    hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `    method: "POST",`,
        `    headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `  }, (res) => { res.resume(); cb(res.statusCode); });`,
        `  req.on("error", () => cb(-1));`,
        `  req.write(body); req.end();`,
        `}`,
        `doPost((s1) => { doPost((s2) => { process.stderr.write(JSON.stringify({s1,s2})+"\\n"); process.exit(0); }); });`,
      ].join("\n"),
      "utf-8",
    );

    const dockerBin = writeFakeDocker(dir, stateDir);
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    const completion = await waitForCompletion(broker, 12_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");

    await broker.ack(handle);

    // No second completion should appear (replay rejected).
    await new Promise((r) => setTimeout(r, 300));
    const second = await broker.listCompleted({ max: 1 });
    expect(second).toHaveLength(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 4. ack() cleanup ──────────────────────────────────────────────────────────

describe("DockerRunAdapter — ack cleanup", () => {
  it("ack() removes supervision entry, removes container, deletes result file", async () => {
    const dir = makeTmpDir("dr-ack-");
    const stateDir = makeTmpDir("dr-ack-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-ack-001";

    // Fake runner: writes result file and POSTs to broker.
    const runnerPath = join(dir, "ack-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const fs = require("node:fs");`,
        `const { CALLBACK_URL, HANDLE, NONCE, RESULT_PATH } = process.env;`,
        `fs.writeFileSync(RESULT_PATH, JSON.stringify({ terminal_status: "in_review" }));`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({`,
        `  hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `  method: "POST",`,
        `  headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `}, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", () => process.exit(1));`,
        `req.write(body); req.end();`,
      ].join("\n"),
      "utf-8",
    );

    const dockerBin = writeFakeDocker(dir, stateDir);
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    expect(adapter.supervisionSize()).toBe(1);

    await waitForCompletion(broker, 12_000);
    // Give the result file a moment to be written.
    await new Promise((r) => setTimeout(r, 100));
    expect(existsSync(resultPath)).toBe(true);

    await adapter.ack(handle);

    expect(adapter.supervisionSize()).toBe(0);
    expect(existsSync(resultPath)).toBe(false);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 5. submit() is non-blocking ───────────────────────────────────────────────

describe("DockerRunAdapter — non-blocking submit", () => {
  it("submit() resolves well before the container finishes", async () => {
    const dir = makeTmpDir("dr-nonblock-");
    const stateDir = makeTmpDir("dr-nonblock-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-nonblock-001";

    // Fake runner: waits 500 ms then POSTs.
    const runnerPath = join(dir, "slow-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `setTimeout(() => {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({`,
        `    hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `    method: "POST",`,
        `    headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `  }, (res) => { res.resume(); process.exit(0); });`,
        `  req.on("error", () => process.exit(1));`,
        `  req.write(body); req.end();`,
        `}, 500);`,
      ].join("\n"),
      "utf-8",
    );

    const dockerBin = writeFakeDocker(dir, stateDir);
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 2_000,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const before = Date.now();
    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    const elapsed = Date.now() - before;

    // submit() should return well before the runner's 500 ms sleep.
    expect(elapsed).toBeLessThan(400);
    expect(typeof handle).toBe("string");

    // Clean up: wait for runner to finish.
    await waitForCompletion(broker, 12_000);
    await adapter.ack(handle);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 6. Orphan sweep ───────────────────────────────────────────────────────────

describe("DockerRunAdapter — orphan sweep", () => {
  it("sweep removes exited containers whose handles are not in supervision", async () => {
    const dir = makeTmpDir("dr-orphan-");
    const stateDir = makeTmpDir("dr-orphan-state-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-orphan-001";

    // Fake runner: exits immediately without POSTing.
    const runnerPath = join(dir, "orphan-runner.cjs");
    writeFileSync(runnerPath, `process.exit(0);\n`, "utf-8");

    const dockerBin = writeFakeDocker(dir, stateDir);
    process.env["FAKE_RUNNER_PATH"] = runnerPath;

    // Use a short sweep interval.
    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      crashGraceMs: 200,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 500,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    // Wait for safety net to fire synthetic failure and broker to receive it.
    const completion = await waitForCompletion(broker, 12_000);
    expect(completion.handle).toBe(handle);

    // Ack the handle so it leaves supervision — making the container an orphan.
    await adapter.ack(handle);
    expect(adapter.supervisionSize()).toBe(0);

    // Give orphan sweep time to run and the result should be no tracked containers.
    await new Promise((r) => setTimeout(r, 1_500));

    // The state file should have no containers with this handle.
    let stateContents: Record<string, unknown> = {};
    try {
      stateContents = JSON.parse(readFileSync(join(stateDir, "containers.json"), "utf-8"));
    } catch {
      // state file may not exist after all containers removed
    }
    expect(Object.keys(stateContents)).toHaveLength(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

