tool_use_result.originalFile:
/**
 * Integration tests for DockerRunAdapter (T8).
 *
 * Docker is not required — a fake docker binary simulates container lifecycle
 * via a state file and real Node child processes. The runner entrypoint path
 * is set to the host path of the fake runner script so the fake docker binary
 * can invoke it directly.
 *
 * Scenarios covered:
 *   1. Happy path — fake container POSTs a valid result; broker delivers it.
 *   2. Wrapper crash before POST — container exits non-zero; safety net fires
 *      a synthetic "failed" completion.
 *   3. Broker-reject (replay) — container POSTs twice; second POST after ack
 *      returns 401; only one completion delivered.
 *   4. ack() removes supervision entry, removes container, unlinks result file.
 *   5. submit() returns a non-empty handle immediately (non-blocking).
 *   6. Orphan sweep removes exited containers not in supervision.
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  rmSync,
  writeFileSync,
  existsSync,
  readFileSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

import { InMemoryBrokerAdapter } from "../src/adapters/broker/in-memory.js";
import { DockerRunAdapter } from "../src/adapters/executor/docker-run.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

async function waitForCompletion(
  broker: InMemoryBrokerAdapter,
  timeoutMs = 15_000,
  pollMs = 50,
): Promise<ReturnType<typeof broker.listCompleted> extends Promise<(infer T)[]> ? T : never> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const items = await broker.listCompleted({ max: 1, lockMs: 30_000 });
    if (items.length > 0) return items[0] as any;
    await new Promise((r) => setTimeout(r, pollMs));
  }
  throw new Error(`waitForCompletion: no completion arrived within ${timeoutMs}ms`);
}

function makeInput(overrides: {
  briefingPath?: string;
  resultPath: string;
  callbackUrl: string;
  nonce: string;
  taskId?: string;
  featureId?: string;
}) {
  return {
    taskId: overrides.taskId ?? "T8",
    featureId: overrides.featureId ?? "runtime-portable-architecture",
    workspaceId: "test-ws",
    taskRepoUrl: "git@github.com:org/repo.git",
    taskRepoBranch: "feature/runtime-portable-architecture-T8",
    taskRepoPath: "/tmp/task-repo",
    briefingPath: overrides.briefingPath ?? "/tmp/briefing.md",
    resultPath: overrides.resultPath,
    sshPrivateKey: "",
    githubToken: "",
    callbackUrl: overrides.callbackUrl,
    nonce: overrides.nonce,
  };
}

/**
 * Write a fake docker binary to `binDir/docker`.
 *
 * The fake binary supports:
 *  - `docker run -d --entrypoint <runner> ...` — spawns the runner script as
 *     a real Node child with env vars extracted from `-e KEY=VALUE` args.
 *     Writes state to stateFile. Returns a fake container ID.
 *  - `docker wait <id>` — polls until the process exits; returns exit code.
 *  - `docker rm <id>` — removes container from state.
 *  - `docker stop <id>` — SIGTERMs the process.
 *  - `docker ps -a --filter label=... --format ...` — lists state entries.
 *
 * State: JSON file at stateFile mapping containerId → { pid, exitCode, labels }.
 */
function writeFakeDocker(binDir: string, stateFile: string): string {
  const dockerBin = join(binDir, "docker");
  const script = /* javascript */ `#!/usr/bin/env node
'use strict';
const cp = require('node:child_process');
const fs = require('node:fs');
const crypto = require('node:crypto');

const STATE_FILE = ${JSON.stringify(stateFile)};

function loadState() {
  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8')); } catch { return {}; }
}
function saveState(s) {
  fs.writeFileSync(STATE_FILE, JSON.stringify(s, null, 2));
}

const args = process.argv.slice(2);
const cmd = args[0];

// ── docker run -d ──────────────────────────────────────────────────────────
if (cmd === 'run' && args.includes('-d')) {
  // Extract --entrypoint (the runner script host path in tests).
  let entrypoint = null;
  const envVars = {};
  const labels = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--entrypoint' && args[i+1]) { entrypoint = args[i+1]; i++; continue; }
    if (args[i] === '-e' && args[i+1]) {
      const eqIdx = args[i+1].indexOf('=');
      if (eqIdx !== -1) {
        envVars[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
      }
      i++;
      continue;
    }
    if (args[i] === '--label' && args[i+1]) {
      const eqIdx = args[i+1].indexOf('=');
      if (eqIdx !== -1) {
        labels[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
      }
      i++;
      continue;
    }
  }
  if (!entrypoint) {
    process.stderr.write('fake-docker run: no --entrypoint provided\\n');
    process.exit(1);
  }
  const containerId = crypto.randomBytes(12).toString('hex');
  const child = cp.spawn('node', [entrypoint], {
    env: { ...process.env, ...envVars },
    stdio: 'inherit',
    detached: true,
  });
  child.unref();
  const state = loadState();
  state[containerId] = { pid: child.pid, exitCode: null, labels };
  saveState(state);
  process.stdout.write(containerId + '\\n');
  process.exit(0);
}

// ── docker wait <id> ───────────────────────────────────────────────────────
if (cmd === 'wait') {
  const cid = args[1];
  const maxWait = 30_000;
  const start = Date.now();
  const poll = () => {
    const state = loadState();
    if (!state[cid]) { process.stdout.write('0\\n'); process.exit(0); }
    const { pid } = state[cid];
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    if (!running) {
      process.stdout.write(String(state[cid].exitCode ?? 0) + '\\n');
      process.exit(0);
    }
    if (Date.now() - start > maxWait) { process.stdout.write('1\\n'); process.exit(0); }
    setTimeout(poll, 100);
  };
  setTimeout(poll, 50);
  return;
}

// ── docker rm <id> ─────────────────────────────────────────────────────────
if (cmd === 'rm') {
  const cid = args[1];
  const state = loadState();
  delete state[cid];
  saveState(state);
  process.exit(0);
}

// ── docker stop <id> ──────────────────────────────────────────────────────
if (cmd === 'stop') {
  const cid = args[1];
  const state = loadState();
  if (state[cid]) { try { process.kill(state[cid].pid, 'SIGTERM'); } catch {} }
  process.exit(0);
}

// ── docker ps -a --filter label=platform.handle --format ... ─────────────
if (cmd === 'ps') {
  const state = loadState();
  const lines = [];
  for (const [cid, entry] of Object.entries(state)) {
    const { pid, labels, exitCode } = entry;
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    const status = running ? 'Up 1 second' : \`Exited (\${exitCode ?? 0}) 1 second ago\`;
    const handle = (labels || {})['platform.handle'] || '';
    if (handle) lines.push(cid + '\\t' + handle + '\\t' + status);
  }
  process.stdout.write(lines.join('\\n') + (lines.length ? '\\n' : ''));
  process.exit(0);
}

process.stderr.write('fake-docker: unknown: ' + args.join(' ') + '\\n');
process.exit(1);
`;
  writeFileSync(dockerBin, script, { mode: 0o755 });
  return dockerBin;
}

// ── Suite setup ───────────────────────────────────────────────────────────────

let broker: InMemoryBrokerAdapter;
let callbackUrl: string;

beforeEach(async () => {
  broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
  await broker.start();
  callbackUrl = broker.getCallbackUrl()!;
});

afterEach(async () => {
  await broker.stop();
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

// ── 1. Happy path ─────────────────────────────────────────────────────────────

describe("DockerRunAdapter — happy path", () => {
  it("submit() returns handle; broker delivers result via callback", async () => {
    const dir = makeTmpDir("dr-happy-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-happy-001";

    const runnerPath = join(dir, "runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/99" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({ hostname: url.hostname, port: Number(url.port), path: url.pathname, method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", (e) => { process.stderr.write(e.message + "\\n"); process.exit(1); });`,
        `req.write(body); req.end();`,
      ].join("\n"),
    );

    const dockerBin = writeFakeDocker(dir, stateFile);

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    expect(typeof handle).toBe("string");
    expect(handle.length).toBeGreaterThan(0);
    expect(adapter.supervisionSize()).toBe(1);

    const completion = await waitForCompletion(broker);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");
    expect(completion.metadata.task_id).toBe("T8");

    await adapter.ack(handle);
    expect(adapter.supervisionSize()).toBe(0);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 2. Wrapper crash before POST ──────────────────────────────────────────────

describe("DockerRunAdapter — wrapper crash before POST", () => {
  it("safety net fires synthetic failed completion when container exits without POSTing", async () => {
    const dir = makeTmpDir("dr-crash-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-crash-001";

    const runnerPath = join(dir, "crash-runner.cjs");
    writeFileSync(runnerPath, `process.exit(1);\n`);

    const dockerBin = writeFakeDocker(dir, stateFile);

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 200,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    const completion = await waitForCompletion(broker, 12_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("failed");
    expect(String(completion.result.blocked_reason)).toMatch(/runner_crashed|runner_no_callback/);

    await broker.ack(handle);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 3. Broker-reject (replay) ─────────────────────────────────────────────────

describe("DockerRunAdapter — broker-reject replay", () => {
  it("second POST after ack returns 401; only one completion delivered", async () => {
    const dir = makeTmpDir("dr-replay-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-replay-001";

    const runnerPath = join(dir, "replay-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `function doPost(cb) {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({ hostname: url.hostname, port: Number(url.port), path: url.pathname, method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => { res.resume(); cb(res.statusCode); });`,
        `  req.on("error", () => cb(-1));`,
        `  req.write(body); req.end();`,
        `}`,
        `doPost((s1) => { doPost((s2) => { process.exit(0); }); });`,
      ].join("\n"),
    );

    const dockerBin = writeFakeDocker(dir, stateFile);

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    const completion = await waitForCompletion(broker, 12_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");

    await broker.ack(handle);

    await new Promise((r) => setTimeout(r, 300));
    const second = await broker.listCompleted({ max: 1 });
    expect(second).toHaveLength(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 4. ack() cleanup ──────────────────────────────────────────────────────────

describe("DockerRunAdapter — ack cleanup", () => {
  it("ack() removes supervision entry, removes container, deletes result file", async () => {
    const dir = makeTmpDir("dr-ack-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-ack-001";

    const runnerPath = join(dir, "ack-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const fs = require("node:fs");`,
        `const { CALLBACK_URL, HANDLE, NONCE, RESULT_PATH } = process.env;`,
        `fs.writeFileSync(RESULT_PATH, JSON.stringify({ terminal_status: "in_review" }));`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({ hostname: url.hostname, port: Number(url.port), path: url.pathname, method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", () => process.exit(1));`,
        `req.write(body); req.end();`,
      ].join("\n"),
    );

    const dockerBin = writeFakeDocker(dir, stateFile);

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    expect(adapter.supervisionSize()).toBe(1);

    await waitForCompletion(broker, 12_000);
    await new Promise((r) => setTimeout(r, 100));
    expect(existsSync(resultPath)).toBe(true);

    await adapter.ack(handle);

    expect(adapter.supervisionSize()).toBe(0);
    expect(existsSync(resultPath)).toBe(false);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 5. submit() is non-blocking ───────────────────────────────────────────────

describe("DockerRunAdapter — non-blocking submit", () => {
  it("submit() resolves well before the container finishes", async () => {
    const dir = makeTmpDir("dr-nonblock-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-nonblock-001";

    const runnerPath = join(dir, "slow-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `setTimeout(() => {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({ hostname: url.hostname, port: Number(url.port), path: url.pathname, method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => { res.resume(); process.exit(0); });`,
        `  req.on("error", () => process.exit(1));`,
        `  req.write(body); req.end();`,
        `}, 500);`,
      ].join("\n"),
    );

    const dockerBin = writeFakeDocker(dir, stateFile);

    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 2_000,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    const before = Date.now();
    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    const elapsed = Date.now() - before;

    expect(elapsed).toBeLessThan(400);
    expect(typeof handle).toBe("string");

    await waitForCompletion(broker, 12_000);
    await adapter.ack(handle);
    adapter.stopOrphanSweep();
  }, 20_000);
});

// ── 6. Orphan sweep ───────────────────────────────────────────────────────────

describe("DockerRunAdapter — orphan sweep", () => {
  it("sweep removes exited containers whose handles are not in supervision (no ack called)", async () => {
    const dir = makeTmpDir("dr-orphan-");
    const stateFile = join(dir, "state.json");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-docker-orphan-001";

    // Runner exits without POSTing to broker.
    const runnerPath = join(dir, "orphan-runner.cjs");
    writeFileSync(runnerPath, `process.exit(0);\n`);

    const dockerBin = writeFakeDocker(dir, stateFile);

    // Short crash grace so safety net fires quickly, removing handle from supervision.
    const adapter = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 200,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 500,
    });

    await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    // Wait for safety net to fire — this removes the handle from supervision
    // and posts synthetic failure to broker. Do NOT call adapter.ack() so the
    // container remains in the fake state file.
    await waitForCompletion(broker, 12_000);
    // Safety net already removed the handle from supervision.
    expect(adapter.supervisionSize()).toBe(0);

    // Container is still in state (ack wasn't called → no docker rm).
    // Give orphan sweep time to run (fires every 500ms).
    await new Promise((r) => setTimeout(r, 1_500));

    // Sweep should have called docker rm and cleared the state.
    let stateContents: Record<string, unknown> = {};
    try {
      stateContents = JSON.parse(readFileSync(stateFile, "utf-8"));
    } catch {
      // State file may be absent if all entries removed.
    }
    expect(Object.keys(stateContents)).toHaveLength(0);

    adapter.stopOrphanSweep();
  }, 20_000);
});

